function Body($s,$n){Get-AICFMethodBody ([pscustomobject]@{Source=$s;Code=(ConvertTo-AICFCodeText $s)}) $n}
$fixture=[IO.File]::ReadAllText((Join-Path $RepositoryRoot 'tests/fixtures/AICF_UnstuckPathHintProbe.c'))
function Rules($s){
 foreach($v in @('aicfUnstuckHistoricalCorridor','if (HistoricalCorridor()) return "684.711 1.5 2276.18"','return "1475.78 36.6684 2473.24"','if (HistoricalCorridor()) return "1581.85 8.59795 2001.13"','vector goal = FarGoal()','vector target = FarGoal()','m_OrderPlanner.AssignPlayerPointOrder(slot, m_USSRFaction, AICF_UnstuckProbe.FarGoal()','GetTargetPosition() != AICF_UnstuckProbe.FarGoal()','historical_source=MIN3_FIRST_STUCK_ORIGIN historical_yaw=UNKNOWN','native_drivable_proven=0 local_or_full_hint_required_after_fault=1')){if(!$s.Contains($v)){'EXPLICIT_NEIGHBOR_GOAL_NORMAL_ORDER_AND_FIRST_STUCK_ORIGIN';break}}
 foreach($v in @('bool actualHint = AICF_UnstuckProbe.s_PreProven && (AICF_UnstuckProbe.s_LocalThree || AICF_UnstuckProbe.s_FullNative)','s_FullNative = hint && detail.Contains("hint_kind=FULL_NATIVE_PATH")','CORRIDOR_AFTER_ACTUAL_FORWARD_CORRECTION_AND_NATIVE_10M','now - m_iUPCorridorMotionAt >= 500','nativeDistance >= 10','m_iUPMoving >= 3','GetMaximumMobilityRecoveryAttempts() == 2','hint_only=1 path_progress=0 maximum_attempts=2 health_unchanged=1 purchases=1 pose_fault=1')){if(!$s.Contains($v)){'ACTUAL_AFTER_FAULT_LOCAL3_OR_FULL_HINT_THEN_NATIVE_MOTION';break}}
 $fault=Body $s 'AICF_UPApplyPoseFault'
 foreach($v in @('AICF_UPOriginalsCurrent(trip, car)','AICF_UnstuckMutationScope.Capture(trip, car)','distance > 0 && distance <= 15','TracePosition(body, null)','!scope.IsCurrent()','setup_fault_only=1 native_progress=0 orientation_preserved=1 health_writes=0','car.GetID().ToString(), trip.GetOperationId()')){if(!$fault.Contains($v)){'FRESH_ONE_POSE_WITH_EXACT_CAR_ORIGINALS_HEALTH_3D15_OBB';break}}
 if($fault-match'SetPhase|SetHealth|SetVelocity|SetAngularVelocity|MarkProgress|SetLOD|ActivateAI|GetCurrentPath\s*\('){'NO_FAKE_POSE_PATH_PHASE_OR_AI_WRITES'}
 $coordinator=$s.Substring($s.IndexOf('modded class AICF_VehicleCoordinator'),$s.IndexOf('modded class AICF_UnstuckPathHint')-$s.IndexOf('modded class AICF_VehicleCoordinator'))
 if(!$coordinator.Contains('if (AICF_UnstuckProbe.FreshSetup() && !AICF_UnstuckProbe.s_PoseFault && !AICF_UnstuckProbe.BrakeDispatch()) trip = null;')){'CORRIDOR_HINT_CAPTURE_REQUIRES_ACTUAL_PRECEDING_POSE_FAULT'}
 $retarget=Body $s 'AICF_UPOriginalRetargetReady'
 foreach($v in @('aicfUnstuckCorridorReturnOriginal','approach > 30','state.GetMobilityRecoveryAttempts() != 0','m_UPOriginalOldWaypointId = state.GetRouteWaypoint().GetID()','m_OrderPlanner.AssignPlayerPointOrder(slot, m_USSRFaction, "1475.78 36.6684 2473.24"','CORRIDOR_NORMAL_COMMAND_CHANGED_CONTEXT_OR_ORIGINAL_DEADLINE','m_iUPOriginalAssignment = slot.GetStrategicAssignmentRevision()','m_iUPOriginalIntent = slot.GetStrategicIntentRevision()','state.GetRouteWaypoint().GetID() == m_UPOriginalOldWaypointId','AICF_VehicleNativeRouteProgress.ValidatePath(path, state.GetRouteEndpoint())','AICF_VehicleNativeRouteProgress.SamePath(path, repeated)','!scope.IsCurrent()','AICF_UPMoveActivityReady(trip)','m_bUPOriginalBound) return true','AICF_UnstuckProbe.s_OriginalRequested = false')){if(!$s.Contains($v)){'NORMAL_ORIGINAL_RETARGET_EXACT_NEW_NATIVE_BOUND_ROUTE';break}}
 if(([regex]::Matches($retarget,'AICF_UPOriginalsCurrent\(trip, car\)')).Count-lt3-or([regex]::Matches($retarget,'GetMobilityRecoveryAttempts\(\) != 0')).Count-lt3){'REPEATED_RETARGET_IDENTITY_DEADLINE_AND_OLD_BUDGET'}
 if($retarget-match'\b(?:SetPhase|SetHealth|SetVelocity|SetOrigin|SetWorldTransform|SetLOD|ActivateAI|MarkProgress|CreditNativeRouteProgress|SetAbsoluteDeadline)\s*\('){'RETARGET_ONLY_NORMAL_PLANNER_COMMAND_NO_WORLD_CLOCK_OR_PATH_WRITES'}
}
$bad=@(Rules $fixture);if($bad.Count){throw "Corridor scope $bad"};$checks=1
foreach($v in @('aicfUnstuckHistoricalCorridor','if (HistoricalCorridor()) return "684.711 1.5 2276.18"','if (HistoricalCorridor()) return "1581.85 8.59795 2001.13"','vector goal = FarGoal()','m_OrderPlanner.AssignPlayerPointOrder(slot, m_USSRFaction, AICF_UnstuckProbe.FarGoal()','AICF_UnstuckProbe.s_PreProven && (AICF_UnstuckProbe.s_LocalThree || AICF_UnstuckProbe.s_FullNative)','now - m_iUPCorridorMotionAt >= 500','nativeDistance >= 10','distance > 0 && distance <= 15','!scope.IsCurrent()','setup_fault_only=1 native_progress=0 orientation_preserved=1 health_writes=0')){if(!@(Rules $fixture.Replace($v,'false')).Count){throw "Corridor unsafe source mutant escaped $v"};$checks++}
foreach($v in @('approach > 30','m_UPOriginalOldWaypointId = state.GetRouteWaypoint().GetID()','m_iUPOriginalAssignment = slot.GetStrategicAssignmentRevision()','m_iUPOriginalIntent = slot.GetStrategicIntentRevision()','state.GetRouteWaypoint().GetID() == m_UPOriginalOldWaypointId','AICF_VehicleNativeRouteProgress.ValidatePath(path, state.GetRouteEndpoint())','AICF_VehicleNativeRouteProgress.SamePath(path, repeated)','CORRIDOR_NORMAL_COMMAND_CHANGED_CONTEXT_OR_ORIGINAL_DEADLINE')){if(!@(Rules $fixture.Replace($v,'false')).Count){throw "Retarget unsafe source mutant escaped $v"};$checks++}
$positive=@(
 '',
 '[UNSTUCK_CORRIDOR_SCOPE] operation=x car=c deadline=1000000 historical_source=MIN3_FIRST_STUCK_ORIGIN native_drivable_proven=0',
 '[UNSTUCK_PROBE_FAR_SCOPE] far_operation=x deadline=1000000 purchases=1 maximum_attempts=2 same_trip=1 same_lease=1',
 '[UNSTUCK_PROBE_POSE_FAULT] operation=x car=c rpl=r deadline=1000000 applied=1 attempts=0 maximum_attempts=2 distance_3d=10 setup_fault_only=1 native_progress=0 orientation_preserved=1 health_writes=0',
 '[VEHICLE_UNSTUCK_ATTEMPT] operation_id=x rpl_id=r attempt=1 relocated=1 mode=SAFE_TERRAIN_REPOSITION hint_only=1 path_progress=0 hint_kind=FULL_NATIVE_PATH',
 '[UNSTUCK_PROBE_CORRECTION] operation=x car=c attempt=1 actual_distance=8 pre_scope=PROVEN pre_hint=1 forward=1 hint_kind=FULL_NATIVE_PATH hint_points=77',
 '[UNSTUCK_CORRIDOR_NATIVE_MOTION] operation=x car=c rpl=r deadline=1000000 attempts=1 maximum_attempts=2 health_unchanged=1 purchases=1 pose_fault=1 hint_only=1 path_progress=0 actual_distance=10 distinct_polls=1 observed_at=1000',
 '[UNSTUCK_CORRIDOR_NATIVE_MOTION] operation=x car=c rpl=r deadline=1000000 attempts=1 maximum_attempts=2 health_unchanged=1 purchases=1 pose_fault=1 hint_only=1 path_progress=0 actual_distance=15 distinct_polls=2 observed_at=1500',
 '[UNSTUCK_CORRIDOR_NATIVE_MOTION] operation=x car=c rpl=r deadline=1000000 attempts=1 maximum_attempts=2 health_unchanged=1 purchases=1 pose_fault=1 hint_only=1 path_progress=0 actual_distance=20 distinct_polls=3 observed_at=2000',
 '[UNSTUCK_PROBE_FINISHED] passed=1 reason=CORRIDOR_AFTER_ACTUAL_FORWARD_CORRECTION_AND_NATIVE_10M'
)
if(!(Test-AICFUnstuckCorridorLog $positive)){throw 'Positive fullnative corridor log rejected'};$cases=1
$local=@($positive|ForEach-Object{$_.Replace('hint_kind=FULL_NATIVE_PATH','hint_kind=LOCAL_FRAGMENT').Replace('hint_points=77','hint_points=3')});if(!(Test-AICFUnstuckCorridorLog $local)){throw 'Positive actualLOCAL3 log rejected'};$cases++
foreach($pair in @(@('native_drivable_proven=0','native_drivable_proven=1'),@('applied=1','applied=0'),@('attempts=0','attempts=1'),@('distance_3d=10','distance_3d=15.001'),@('orientation_preserved=1','orientation_preserved=0'),@('health_writes=0','health_writes=1'),@('purchases=1','purchases=2'),@('same_lease=1','same_lease=0'),@('actual_distance=8','actual_distance=100'),@('actual_distance=8','actual_distance=NaN'),@('forward=1','forward=0'),@('pre_scope=PROVEN','pre_scope=UNPROVEN'),@('hint_kind=FULL_NATIVE_PATH','hint_kind=UNKNOWN'),@('relocated=1','relocated=0'),@('mode=SAFE_TERRAIN_REPOSITION','mode=ROUTE_REBUILD_ONLY'),@('path_progress=0','path_progress=1'),@('health_unchanged=1','health_unchanged=0'),@('actual_distance=10','actual_distance=9.99'),@('observed_at=1500','observed_at=1001'))){if(Test-AICFUnstuckCorridorLog @($positive|ForEach-Object{$_.Replace($pair[0],$pair[1])})){throw "Unsafe corridor log accepted $pair"};$cases++}
for($i=1;$i-lt$positive.Count;$i++){$without=@();for($j=0;$j-lt$positive.Count;$j++){if($i-ne$j){$without+=$positive[$j]}};if(Test-AICFUnstuckCorridorLog $without){throw "Missing actual corridor proof accepted $i"};$cases++}
if(Test-AICFUnstuckCorridorLog @($local|ForEach-Object{$_.Replace('hint_points=3','hint_points=2')})){throw 'LOCAL2 incorrectly accepted asLOCAL3'};$cases++
$two=@();for($i=0;$i-lt$positive.Count;$i++){
 if($i-eq4){$two+='[VEHICLE_UNSTUCK_ATTEMPT] operation_id=x rpl_id=r attempt=1 relocated=1 mode=SAFE_TERRAIN_REPOSITION hint_kind=UNKNOWN';$two+='[UNSTUCK_PROBE_CORRECTION] operation=x car=c attempt=1 actual_distance=8 pre_scope=UNPROVEN pre_hint=0 forward=0 hint_kind=UNKNOWN'}
 $line=$positive[$i];if($i-ge4){$line=$line.Replace('attempt=1','attempt=2').Replace('attempts=1','attempts=2')};$two+=$line
}
if(!(Test-AICFUnstuckCorridorLog $two)){throw 'Two actual corrections with earlierUNKNOWN legitimate hint rejected'};$cases++
foreach($value in @('100','NaN','Infinity')){$mutated=@($two);$mutated[5]=$mutated[5].Replace('actual_distance=8','actual_distance='+$value);if(Test-AICFUnstuckCorridorLog $mutated){throw "Earlier unsafe correction accepted $value"};$cases++}
$mutated=@($two);$mutated[5]=$mutated[5].Replace('attempt=1','attempt=2');if(Test-AICFUnstuckCorridorLog $mutated){throw 'Duplicate physical attempt accepted'};$cases++
$missing=@();for($i=0;$i-lt$two.Count;$i++){if($i-ne4){$missing+=$two[$i]}};if(Test-AICFUnstuckCorridorLog $missing){throw 'Earlier actual production receipt missing accepted'};$cases++
$retarget=@();for($i=0;$i-lt$positive.Count;$i++){
 if($i-eq3){$retarget+='[UNSTUCK_CORRIDOR_RETARGET_REQUEST] operation=x car=c deadline=1000000 purchases=1 budget_before=0 normal_owner_command=1 approach_3d=26 old_wp=old old_route=1 assignment=4 intent=3';$retarget+='[UNSTUCK_CORRIDOR_ORIGINAL_BOUND] operation=x car=c deadline=1000000 purchases=1 budget_before=0 normal_adoption=1 same_trip=1 same_lease=1 assignment=4 intent=3 new_wp=new new_route=1 native_points=77'}
 $retarget+=$positive[$i]
}
if(!(Test-AICFUnstuckCorridorLog $retarget -RequireOriginalRetarget)){throw 'Actualnormal retarget withsame resetgeneration butnew waypoint rejected'};$cases++
if(Test-AICFUnstuckCorridorLog $positive -RequireOriginalRetarget){throw 'Missing explicit retarget proof accepted'};$cases++
foreach($pair in @(@('approach_3d=26','approach_3d=30.001'),@('new_wp=new','new_wp=old'),@('native_points=77','native_points=0'),@('normal_owner_command=1','normal_owner_command=0'),@('normal_adoption=1','normal_adoption=0'),@('same_trip=1','same_trip=0'),@('budget_before=0','budget_before=1'))){if(Test-AICFUnstuckCorridorLog @($retarget|ForEach-Object{$_.Replace($pair[0],$pair[1])}) -RequireOriginalRetarget){throw "Unsafeoriginalretarget accepted $pair"};$cases++}
foreach($field in @('deadline=1000000','assignment=4','intent=3')){$mutated=@($retarget);$mutated[4]=$mutated[4].Replace($field,$field+'9');if(Test-AICFUnstuckCorridorLog $mutated -RequireOriginalRetarget){throw "Changedretargetcontext accepted $field"};$cases++}
"PASS Unstuck corridor probe: source_controls=$checks log_cases=$cases native=NOT_RUN"
